async (page) => {
  const fs = require('fs');
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Make the runner script executable
    fs.chmodSync('/tmp/mcp-workspace/run_backup.sh', '755');

    // Run the runner script which will make the backup script executable and run it
    const { stdout, stderr } = await execPromise('/tmp/mcp-workspace/run_backup.sh');

    return `Script output:\n${stdout}\n${stderr}`;
  } catch (error) {
    return `Error running script: ${error.message}\nstdout: ${error.stdout}\nstderr: ${error.stderr}`;
  }
}

async (page) => {
  const fs = require('fs');
  const path = require('path');

  try {
    // Source file
    const sourceFile = '/tmp/mcp-workspace/RELEASE_NOTES_TEMPLATE.md';
    // Destination file
    const destFile = '/tmp/mcp-workspace/backup/RELEASE_NOTES_TEMPLATE.md';

    // Check if source file exists
    if (fs.existsSync(sourceFile)) {
      // Copy the file
      fs.copyFileSync(sourceFile, destFile);
      return 'Successfully copied RELEASE_NOTES_TEMPLATE.md to backup directory';
    } else {
      return 'Source file does not exist';
    }
  } catch (error) {
    return `Error copying file: ${error.message}`;
  }
}
